CREATE TABLE IF NOT EXISTS public.symbols (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, description text NOT NULL DEFAULT '', category_id uuid REFERENCES public.categories(id) ON DELETE SET NULL, image_prompt text NOT NULL DEFAULT '', image_url text, ai_generated boolean NOT NULL DEFAULT false, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.symbols TO anon; GRANT SELECT, INSERT, UPDATE, DELETE ON public.symbols TO authenticated; GRANT ALL ON public.symbols TO service_role; ALTER TABLE public.symbols ENABLE ROW LEVEL SECURITY; CREATE POLICY "active symbols public read" ON public.symbols FOR SELECT TO anon, authenticated USING (is_active); CREATE POLICY "admins manage symbols" ON public.symbols FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin')); CREATE INDEX IF NOT EXISTS symbols_category_idx ON public.symbols(category_id);